result:
	.empty-box{
	  height: 160px;
	  background-color: #F3F9FF;
	  .shan{
		width: 65px !important;
		height: 50px !important;
	  }
	  &.style3{
		  width: 16px;
		  border-radius: 0;
		  height: 144px;
		  img {
			  width: 16px;
			  height: 100%;
		  }
	  }
	  &.on{
		  flex: 1;
		  margin: 0 12px;
		  height: 160px;
	  }
	}
	.banDot{
		.dot{
			padding: 0 40px;
		}
	}
	.dot {
	  position: absolute;
	  left: 0;
	  bottom: 25px;
	  width: 100%;
	  display: flex;
	  align-items: center;
	  z-index: 9;
	  padding: 0 30px;

	  &.on{
		  .dot-item{
			  width: 5px;
			  height: 5px;
			  &.ons{
				 width: 9px;
				 height: 5px;
				 border-radius: 4px; 
			  }
		  }
	  }

	  &.on2{
		  .dot-item{
			  width: 10px;
			  height: 3px;
			  border-radius: 4px;
		  }
	  }

	  .dot-item {
	    width: 6px;
	    height: 6px;
	    background: #DDDDDD;
	    border-radius: 50%;
	    margin: 0 3px;
	  }

	  .line-dot{
		  width: 30px;
		  height: 3px;
		  border-radius: 4px;
		  background-color: #DDDDDD;
		  .item{
			  width: 10px;
			  height: 100%;
			  border-radius: 4px;
			  background-color: #E93323;
		  }
	  }

	  &.number{
		  width: 40px;
		  height: 18px;
		  border-radius: 100px;
		  background: rgba(0,0,0,0.3);
		  color: #fff;
		  font-size: 8px;
		  .num{
			  width: 22px;
			  height: 100%;
			  border-radius: 20px 0 20px 20px;
			  background: rgba(0,0,0,0.1);
			  font-size: 10px;
			  text-align: center
			  line-height: 18px;
		  }
		  .numCon{
			  width: 18px;
			  text-align: center;
			  line-height: 18px;
		  }
	  }
	}
    .homeComb{
        width: 100%;
        position: relative;
        overflow: hidden;
        padding-bottom: 13px;
        &.on{
            background: rgba(0,0,0,0.2);
        }
        .bgImg{
            position: absolute;
            width: 100%;
            height: 100%;
            top:0;
            z-index: 1;
            filter:blur(0);
            overflow: hidden;
            img {
                width: 100%;
                height: 100%;
                filter: blur(15px);
                transform: scale(1.5);
            }
        }
		.searchBox{
		    position: relative;
		    padding: 9px 12px 0 12px;
		    z-index: 1;
		    img {
		        width: 69px;
		        height: 30px;
		        display: inline-block;
		    }
		    .box{
		        width: 275px;
		        height: 29px;
		        border-radius: 16px 16px 16px 16px;
		        background-color: rgba(228, 228, 228, 0.4);
		        padding: 0 12px;
		        font-size: 12px;
		        font-weight: 400;
		        color: rgba(255, 255, 255, 0.5);
		        &.on{
		            width: 100%;
		        }
				.hot{
					color: #fff;
				}
		    }
		}
		.nav{
		    position: relative
		    z-index: 1;
		    padding: 0 12px;
		    width: 100%;
		    box-sizing: border-box;
		    height: 42px;
			.list{
				width: 328px;
				overflow: hidden
				.listCon{
					width: 10000%;
				}
			}
		    .iconfont{
		        font-size: 14px;
		        color: #fff;
		    }
		    .bar{
		        width: 1px;
		        height: 15px;
		        background: linear-gradient(135deg, rgba(215,215,215,0) 0%, #fff 50%, rgba(215,215,215,0) 100%);
		        margin: 0 5px;
		    }
		    .item{
		        font-weight: 400;
		        color: #FFFFFF;
		        font-size: 15px;
		        position: relative
		        &.on{
		            font-size: 16px;
					margin-left: 0 !important;
		            .lines{
		                position: absolute;
		                width: 10px;
		                height: 2px;
		                background: #FFFFFF;
		                transform: translateX(-50%);
		                left:50%;
		                bottom: 0
		            }
		        }
		    }
		}
		.banner{
		    width: 355px;
		    height: 160px;
		    position: relative
		    z-index: 1;
		    border-radius: 6px;
		    margin: 0 auto;
		    &.on{
		        margin-top: 15px;
		    }
			&.ons{
				width: 100%
			}
		    img {
		        width: 100%;
		        height: 100%;
		        border-radius: 6px;
		    }
		}
    }
